<template><section class="mole"><header><button @click="$router.push('/personal/games')">← 游戏大厅</button><h1>打地鼠</h1></header><div class="info"><b>{{ score }} 分</b><span>{{ time }} 秒</span><button @click="start">{{ running?'重新开始':'开始游戏' }}</button></div><div class="holes"><button v-for="i in 9" :key="i" @click="hit(i-1)"><span v-if="active===i-1">🐹</span></button></div><h2 v-if="!running&&time===0">时间到！最终得分 {{ score }}</h2><GameLeaderboard game="whack-a-mole" :score="score" /></section></template>
<script setup lang="ts">import{onBeforeUnmount,ref}from'vue';const score=ref(0),time=ref(30),active=ref(-1),running=ref(false);let clock=0,mover=0;function start(){clearInterval(clock);clearInterval(mover);score.value=0;time.value=30;running.value=true;active.value=~~(Math.random()*9);mover=window.setInterval(()=>active.value=~~(Math.random()*9),650);clock=window.setInterval(()=>{if(--time.value<=0){running.value=false;active.value=-1;clearInterval(clock);clearInterval(mover)}},1000)}function hit(i:number){if(running.value&&i===active.value){score.value++;active.value=-1}}onBeforeUnmount(()=>{clearInterval(clock);clearInterval(mover)})</script>
<style scoped>.mole{max-width:560px;margin:auto;text-align:center;padding:15px}.mole header{display:flex;align-items:center;gap:30px}.mole button{border:1px solid var(--c-border);background:var(--c-bg-card);color:var(--c-text-2);border-radius:9px;padding:9px}.info{display:flex;justify-content:center;gap:30px;align-items:center;margin:22px}.info b{font-size:24px;color:var(--c-cyan)}.holes{display:grid;grid-template-columns:repeat(3,130px);gap:15px;justify-content:center}.holes button{height:110px;border-radius:50%;background:#5a3928;box-shadow:inset 0 14px 15px #24130b;font-size:50px}.mole h2{color:var(--c-purple)}@media(max-width:470px){.holes{grid-template-columns:repeat(3,27vw)}.holes button{height:24vw}.mole header{flex-wrap:wrap}}</style>
